    [InlineData("func put<s/W, V>(m: s/W, y: s/V) -> i32\n    s is owner or ref\n    return 0\nfunc call<X>(x: X) -> i32\n    X is Owned\n    let f: (i32, X) -> i32 = put<i32, X>\n    return 0\n", "clean")] // ex1x
